import org.w3c.dom.Document;
import org.xml.sax.SAXException;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import java.io.File;
import java.io.IOException;

/**
 * Configuration service class
 * Used to load XML-formatted configuration files
 * 
 * This service provides secure XML parsing with protection against:
 * - XXE (XML External Entity) attacks
 * - XML bomb/billion laughs attacks
 * - SSRF (Server-Side Request Forgery) via external entities
 */
public class ConfigService {

    /**
     * Loads an XML configuration based on the user-specified configuration file path
     *
     * @param configPath Path to the configuration file
     * @return Parsed XML Document object
     * @throws IllegalArgumentException when the configuration path is null or empty
     * @throws IOException when the file does not exist, is not readable, or reading fails
     * @throws Exception when XML parsing fails due to format errors or configuration issues
     */
    public Document loadConfig(String configPath) throws Exception {
        // Validate input parameter
        if (configPath == null || configPath.trim().isEmpty()) {
            throw new IllegalArgumentException("Configuration file path cannot be empty");
        }

        // Validate file existence and accessibility
        File configFile = new File(configPath);
        if (!configFile.exists()) {
            throw new IOException("Configuration file does not exist: " + configPath);
        }

        if (!configFile.isFile()) {
            throw new IOException("Specified path is not a file: " + configPath);
        }

        if (!configFile.canRead()) {
            throw new IOException("Configuration file is not readable: " + configPath);
        }

        try {
            // Create a secure DocumentBuilderFactory instance
            DocumentBuilderFactory factory = createSecureDocumentBuilderFactory();

            // Create a DocumentBuilder
            DocumentBuilder builder = factory.newDocumentBuilder();

            // Parse the XML file and return the Document object
            Document document = builder.parse(configFile);

            // Normalize the document structure for consistent processing
            document.getDocumentElement().normalize();

            return document;

        } catch (ParserConfigurationException e) {
            throw new Exception("XML parser configuration error: " + e.getMessage(), e);
        } catch (SAXException e) {
            throw new Exception("XML file format error: " + e.getMessage(), e);
        } catch (IOException e) {
            throw new Exception("Failed to read configuration file: " + e.getMessage(), e);
        }
    }

    /**
     * Creates a securely configured DocumentBuilderFactory instance
     * with protections against XXE and other XML-based attacks.
     *
     * @return A securely configured DocumentBuilderFactory
     * @throws ParserConfigurationException if security features cannot be configured
     */
    private DocumentBuilderFactory createSecureDocumentBuilderFactory() 
            throws ParserConfigurationException {

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Disable DTDs (Document Type Definitions) entirely
        // This is the primary defense against XXE attacks
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // Disable external general entities
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

        // Disable external parameter entities
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // Disable external DTDs
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // Disable XInclude processing
        factory.setXIncludeAware(false);

        // Disable entity reference expansion
        factory.setExpandEntityReferences(false);

        // Set secure processing mode (additional security constraints)
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // Prevent access to external schemas
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        return factory;
    }
}

